 ?><div class="detail-grid"><div class="stack"><?php panel_start('Role directory');foreach(rows('SELECT r.*,(SELECT COUNT(*) FROM users u WHERE u.role=r.role_key) member_count FROM roles r ORDER BY is_system DESC,role_name')as $x):?><div class="activity-item"><?=icon('shield')?><div class="grow"><strong class="small"><?=e($x['role_name'])?></strong><p><?=e($x['description'])?></p><small><?=e($x['role_key'])?> · <?=(int)$x['member_count']?> primary accounts · <?=$x['active']?'Active':'Inactive'?></small></div><a class="btn btn-outline btn-sm" href="<?=e(url('admin/roles?edit='.$x['role_key']))?>"><?=$x['role_key']==='admin'?'View':'Edit'?></a></div><?php endforeach;panel_end();?><div class="notice">Permissions govern both page access and actions. Department access never grants cross-department access. Role changes revoke affected sessions. The administrator role is protected, and public citizen accounts cannot receive staff permissions.</div></div><div><?php panel_start($r?'Role permissions':'Create a role');if($key==='admin'):?><p class="small muted">Administrators have all permissions. This role cannot be disabled or modified.</p><ul class="checklist"><?php foreach(permission_catalogue()as $permission=>$x):?><li><?=e($x[1])?> <span class="mono"><?=e($permission)?></span></li><?php endforeach;?></ul><?php else:?><form method="post" action="<?=e(url('admin/roles'))?>"><?=csrf_field()?><?php field('role_key','Unique role key',$r['role_key']??'','text','required maxlength="50" '.($r?'readonly':''));field('role_name','Role name',$r['role_name']??'','text','required maxlength="100"');textarea_field('description','Purpose',$r['description']??'',2000);?><label class="checkbox"><input name="active" type="checkbox" value="1" <?=!$r||$r['active']?'checked':''?>> Role active</label><?php $group='';foreach(permission_catalogue()as $permission=>$x):if($group!==$x[0]){$group=$x[0];echo '<h3 class="mt">'.e($group).'</h3>'; }?><label class="checkbox"><input name="permissions[]" type="checkbox" value="<?=e($permission)?>" <?=in_array($permission,$granted,true)?'checked':''?>><span><?=e($x[1])?><small class="block mono"><?=e($permission)?></small></span></label><?php endforeach;?><div class="actions"><button class="btn btn-primary" type="submit">Save role</button><a class="btn btn-outline" href="<?=e(url('admin/roles'))?>">Create new</a></div></form><?php endif;panel_end();?></div></div><?php
 }
 if($path==='/admin/templates'){
