 ?><div class="flex mb"><?php foreach(rows('SELECT * FROM email_templates ORDER BY id')as $x):?><a class="btn <?=$x['template_key']===$key?'btn-primary':'btn-outline'?>" href="<?=e(url('admin/templates?edit='.$x['template_key']))?>"><?=e($x['name'])?></a><?php endforeach;?><a class="btn btn-outline" href="<?=e(url('admin/templates?edit=new'))?>">New template</a></div><div class="grid grid-2"><?php panel_start($t?'Edit email template':'Add email template');?><form method="post" action="<?=e(url('admin/templates'))?>"><?=csrf_field()?><?php field('template_key','Template key',$t['template_key']??'','text','required maxlength="60" '.($t?'readonly':''));field('name','Template name',$t['name']??'','text','required maxlength="140"');field('subject','Subject',$t['subject']??'{{title}}','text','required maxlength="180"');?><div class="field"><label for="emailEditor">HTML message</label><div class="editor-toolbar" role="toolbar" aria-label="Email formatting"><?php foreach(['bold'=>'Bold','italic'=>'Italic','insertUnorderedList'=>'Bullet list','insertOrderedList'=>'Numbered list']as $command=>$text):?><button class="btn btn-outline btn-sm" type="button" data-format="<?=e($command)?>"><?=e($text)?></button><?php endforeach;?></div><div id="emailEditor" contenteditable="true" role="textbox" aria-multiline="true" class="email-editor"><?=clean_email_html($t['html_body']??'<h2>{{title}}</h2><p>Hello {{name}},</p><p>{{message}}</p><p><a href="{{link}}">Open your workspace</a></p>')?></div><textarea id="emailSource" name="html_body" rows="7" required><?=e($t['html_body']??'<h2>{{title}}</h2><p>Hello {{name}},</p><p>{{message}}</p><p><a href="{{link}}">Open your workspace</a></p>')?></textarea><small>The visual editor and HTML source stay in sync. Unsafe tags and attributes are removed when saving.</small></div><?php textarea_field('plain_body','Plain text alternative',$t['plain_body']??"Hello {{name}},\n\n{{message}}\n\n{{link}}",12000);?><label class="checkbox"><input name="active" type="checkbox" value="1" <?=!$t||$t['active']?'checked':''?>> Available for new messages</label><button class="btn btn-primary" type="submit">Save template</button></form><?php panel_end();panel_start('Saved template preview');if($preview):?><strong class="small">Subject: <?=e($preview['subject'])?></strong><div class="email-preview mt"><?=$preview['html_body']?></div><?php endif;?><hr class="divider"><h3>Available placeholders</h3><p class="small mono">{{name}} {{title}} {{message}} {{reference}} {{status}} {{service}} {{department}} {{link}} {{app_name}}</p><p class="small muted">The service_update template is used for request events. welcome is used for new citizen accounts. Notifications keep the rendered message in the outbox for a stable delivery record. Delivery adds the workspace email header and footer.</p><?php panel_end();?></div><?php
 }
 if($path==='/admin/compose'){
 $q=mb_substr(trim((string)($_GET['q']??'')),0,100);$recipients=rows("SELECT id,name,email FROM users WHERE status='active'".($q!==''?' AND (name LIKE ? OR email LIKE ?)':'').' ORDER BY name LIMIT 100',$q!==''?['%'.$q.'%','%'.$q.'%']:[]);
 ?><div class="grid grid-2"><?php panel_start('Create a service notice');?><form method="get" action="<?=e(url('admin/compose'))?>" class="filters"><?php field('q','Find a recipient',$q,'search');?><button class="btn btn-outline" type="submit">Find</button></form><form method="post" action="<?=e(url('admin/compose'))?>" data-confirm="Create this notice and queue any selected external delivery?"><?=csrf_field()?><?php $opts=[''=>'Choose a registered recipient'];foreach($recipients as $x)$opts[$x['id']]=$x['name'].' — '.$x['email'];select_field('recipient_id','Recipient',$opts,'','required');select_field('channel','Delivery channel',['in_app'=>'In-app only','email'=>'In-app and email','sms'=>'In-app and SMS']);$opts=[];foreach(rows('SELECT * FROM email_templates WHERE active=1 ORDER BY name')as $t)$opts[$t['template_key']]=$t['name'];select_field('template_key','Message template',$opts,'general_notice','required');field('title','Message title','','text','required maxlength="180"');textarea_field('message','Message','',8000);?><button class="btn btn-primary" type="submit">Create and queue notice</button></form><?php panel_end();panel_start('Controlled communication');?><ul class="checklist"><li>Select a registered, active recipient.</li><li>Routine email and SMS respect account preferences.</li><li>Messages are recorded in-app immediately.</li><li>External messages enter the outbox for scheduled delivery.</li><li>Disabled channels retain messages as configuration required.</li><li>Every composed notice is recorded in the audit trail.</li></ul><p class="small muted">Recipient search returns up to 100 accounts. Use a name or email to narrow the list.</p><?php panel_end();?></div><?php
 }
 if($path==='/admin/outbox/detail'){
 $m=row('SELECT o.*,u.name user_name FROM outbox o JOIN users u ON u.id=o.user_id WHERE o.id=?',[(int)($_GET['id']??0)]);if(!$m)abort_page(404,'Delivery record not found.');$sensitive=str_contains($m['subject'],'Reset your')||str_starts_with($m['template_key']??'','auth_');panel_start('Delivery record');?><dl class="detail-meta"><?php foreach(['Recipient'=>$m['user_name'].' — '.$m['recipient'],'Channel'=>label($m['channel']),'Subject'=>$m['subject'],'State'=>label($m['state']),'Attempts'=>(string)$m['attempts'],'Queued'=>dates($m['created_at'],true),'Provider accepted'=>dates($m['sent_at'],true),'Next retry'=>dates($m['next_attempt_at'],true),'Provider ID'=>$m['provider_id']?:'—','Last result'=>$m['last_error']?:'No error recorded']as $k=>$v):?><div><dt><?=e($k)?></dt><dd><?=e($v)?></dd></div><?php endforeach;?></dl><hr class="divider"><?php if($sensitive):?><p class="notice">Authentication message content is hidden to protect reset links and account security.</p><?php else:?><h3>Message</h3><?php if($m['html_body']):?><div class="email-preview"><?=clean_email_html($m['html_body'])?></div><?php endif;?><pre class="diagnostic"><?=e($m['body'])?></pre><?php endif;?><a class="btn btn-outline" href="<?=e(url('admin/outbox'))?>">Back to outbox</a><?php panel_end();
 }
